function getAmtrakMappedStop(stop_id)
{
  var s = stop_id;
  if(stop_id == "T_BNT-0000") s = "North Station";
  else if(stop_id == "T_NEC-2287") s = "South Station";
  else if(stop_id == "T_NHRML-0127") s = "Anderson/ Woburn";
  else if(stop_id == "T_WR-0329") s = "Haverhill";
  else if(stop_id == "T_NEC-2276") s = "Back Bay";
  else if(stop_id == "T_NEC-2173") s = "Route 128";
  else if(stop_id == "T_NEC-1851") s = "Providence";
  else if(stop_id == "T_WML-0214") s = "Framingham";
  else if(stop_id == "T_WML-0442-CS") s = "Worcester";
  return(s);
}

function isTsubwayStop(s)
{
  var b = false;
  if(s.indexOf("T_") == 0)
  {
    var r = s.substring(2);
    if(!isNaN(r)) b = true;
  }
  return(b);
}

